const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      authorized: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      authorized: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Outsiders are not permitted. Please log in again."
    }
  }];
}

const authUserId = String(claims.sub).trim();
const authUserRole = String(claims.role || 'EMPLOYEE').toUpperCase();
const authUserEmail = String(claims.email || '').trim();

const webhookNode = $('Webhook - POST /attendance-full').first().json || {};
const webhookBody = webhookNode.body || {};
const requestedId = (webhookBody.employeeId || webhookBody.email || '').trim();

let targetEmployeeId = authUserId;
if (requestedId) {
  const isSelf = (requestedId === authUserId || requestedId.toLowerCase() === authUserEmail.toLowerCase());
  if (isSelf) {
    targetEmployeeId = authUserId;
  } else if (authUserRole === 'ADMIN') {
    targetEmployeeId = requestedId;
  } else {
    return [{
      json: {
        authorized: false,
        statusCode: 403,
        error: "Forbidden: You are not authorized to view another employee's attendance records."
      }
    }];
  }
}

// Target month (e.g. '2026-11' or current month)
let targetMonth = (webhookBody.month || '').trim();
if (!/^\d{4}-\d{2}$/.test(targetMonth)) {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  targetMonth = `${y}-${m}`;
}

return [{
  json: {
    authorized: true,
    targetEmployeeId: targetEmployeeId,
    targetMonth: targetMonth,
    authUser: {
      id: authUserId,
      role: authUserRole,
      email: authUserEmail
    }
  }
}];

const items = $input.all();
const data = (items.length > 0 && items[0].json) ? items[0].json : {};

if (!data.employee_found || !data.employee) {
  return [{
    json: {
      success: false,
      statusCode: 404,
      error: "Employee not found in database."
    }
  }];
}

const today = data.today_attendance || {};
const isCheckedIn = !!today.check_in;
const isCheckedOut = !!today.check_out;

// Calculate working days in selected month (Mon - Sat are 6 working days, Sunday is weekly off)
const selectedMonth = data.selected_month || new Date().toISOString().substring(0, 7);
const [yrStr, moStr] = selectedMonth.split('-');
const year = parseInt(yrStr, 10);
const month = parseInt(moStr, 10) - 1;
const daysInMonth = new Date(year, month + 1, 0).getDate();

let holidaysList = [];
try {
  holidaysList = typeof data.holidays === 'string' 
    ? JSON.parse(data.holidays) 
    : (Array.isArray(data.holidays) ? data.holidays : []);
} catch (e) {
  holidaysList = [];
}
const closedHolidays = new Set(
  holidaysList.filter(h => h && h.isOfficeClosed !== false).map(h => h.date)
);

let totalWorkingDays = 0;
for (let d = 1; d <= daysInMonth; d++) {
  const dayOfWeek = new Date(year, month, d).getDay();
  const dStr = year + '-' + String(month + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0');
  const isSunday = (dayOfWeek === 0);
  const isHoliday = closedHolidays.has(dStr);
  if (!isSunday && !isHoliday) {
    totalWorkingDays++;
  }
}

const monthly = data.monthly_summary || {};

let recordsList = [];
try {
  recordsList = typeof data.month_records === 'string' 
    ? JSON.parse(data.month_records) 
    : (Array.isArray(data.month_records) ? data.month_records : []);
} catch (e) {
  recordsList = [];
}

let todayPunches = [];
try {
  todayPunches = typeof today.punches === 'string'
    ? JSON.parse(today.punches)
    : (Array.isArray(today.punches) ? today.punches : []);
} catch (e) {
  todayPunches = [];
}

return [{
  json: {
    success: true,
    statusCode: 200,
    month: selectedMonth,
    daysInMonth: daysInMonth,
    employee: {
      id: data.employee.id,
      firstName: data.employee.first_name,
      lastName: data.employee.last_name,
      email: data.employee.email,
      phone: data.employee.phone,
      avatarUrl: data.employee.avatar_url || null,
      designation: data.employee.designation,
      workLocation: data.employee.work_location || 'Chinar Park, Teghoria, Kolkata (In-Office)',
      role: data.employee.role || 'EMPLOYEE'
    },
    todayRecord: {
      id: today.id || null,
      date: today.date || new Date().toISOString().split('T')[0],
      checkIn: today.check_in || null,
      checkOut: today.check_out || null,
      status: today.status || 'PENDING',
      statusLabel: today.status_label || (isCheckedIn ? 'Checked In' : 'Awaiting Punch'),
      expectedCheckOutTime: today.expected_check_out_time || '19:00',
      workDurationMinutes: parseInt(today.work_duration_minutes || '0', 10),
      totalDurationMinutes: parseInt(today.total_duration_minutes || '0', 10),
      lunchDurationMinutes: parseInt(today.lunch_duration_minutes || '60', 10),
      lateAllowanceUsed: today.late_allowance_used || null,
      isHalfDayCase: !!today.is_half_day_case,
      isCheckedIn: isCheckedIn,
      isCheckedOut: isCheckedOut,
      punches: todayPunches,
      notes: today.notes || null
    },
    summary: {
      monthKey: selectedMonth,
      totalWorkingDays: totalWorkingDays,
      presentDays: parseInt(monthly.present_days || '0', 10),
      onTimeDays: parseInt(monthly.on_time_days || '0', 10),
      withinBufferDays: parseInt(monthly.within_buffer_days || '0', 10),
      lateDays: parseInt(monthly.late_days || '0', 10),
      lateAllowancesUsed: parseInt(monthly.late_allowances_used || '0', 10),
      lateAllowancesRemaining: Math.max(0, 3 - parseInt(monthly.late_allowances_used || '0', 10)),
      halfDays: parseInt(monthly.half_days || '0', 10),
      absentDays: parseInt(monthly.absent_days || '0', 10),
      leaveDays: parseInt(monthly.leave_days || '0', 10),
      holidays: parseInt(monthly.holidays || '0', 10),
      totalWorkHours: parseFloat(monthly.total_work_hours || '0.0'),
      averageHoursPerDay: parseFloat(monthly.average_hours_per_day || '0.0')
    },
    records: recordsList,
    holidays: holidaysList,
    rules: {
      officeOpening: "10:00 AM",
      graceBufferLimit: "10:20 AM (Must stay until 07:30 PM)",
      maximumLateArrivalTime: "10:45 AM",
      monthlyLateAllowance: 3,
      lunchBreakMinutes: 60,
      halfDayCutoff: "Arrival after 10:45 AM or after 3 late allowances exhausted"
    }
  }
}];
